const HIDDEN_DIAGNOSTICS=new Set(["status","provenance","legalConclusion","staticHtmlOnly","javascriptRendered","interactiveFlowExecuted","visiblePriceEvidenceStrength"]);
const diagnosticValue=(key:string,value:unknown):string=>{
 if(value===true)return "Ja"; if(value===false)return "Nee"; if(value==null||value==="")return "—";
 if(Array.isArray(value))return value.length?value.map(v=>typeof v==="object"?JSON.stringify(v):String(v)).join(" · "):"—";
 if(key==="availability"&&typeof value==="string")return /instock/i.test(value)?"Op voorraad":/outofstock|soldout/i.test(value)?"Niet op voorraad":/preorder|backorder/i.test(value)?"Pre-order / nalevering":value.replace(/^https?:\/\/schema\.org\//,"");
 return String(value);
};
const diagnosticRows=(data:unknown):Array<[string,string]>=>{
 if(!data||typeof data!=="object")return [];
 const rows:Array<[string,string]>=[];
 for(const [key,value] of Object.entries(data)){
  if(HIDDEN_DIAGNOSTICS.has(key))continue;
  if(key==="product"&&value&&typeof value==="object"){for(const [pk,pv] of Object.entries(value as Record<string,unknown>))rows.push([DIAGNOSTIC_LABELS[pk]||pk,diagnosticValue(pk,pv)]);continue;}
  rows.push([DIAGNOSTIC_LABELS[key]||key,diagnosticValue(key,value)]);
 }
 return rows;
};
const CONFIDENCE_NL:Record<string,string>={high:"hoog",medium:"gemiddeld",low:"laag"};
const assessedCounts=(r:any)=>{
  const all=[...(r?.seo?.checks||[]),...(r?.geo?.checks||[])];
  const applicable=all.filter((c:any)=>c.status!=="not_applicable");
  const assessed=applicable.filter((c:any)=>c.status!=="unable_to_confirm");
  return {assessed:assessed.length,applicable:applicable.length,unconfirmed:applicable.length-assessed.length};
};
const reliabilityOf=(r:any)=>{
  const c=assessedCounts(r);
  const scoreCov=c.applicable?c.assessed/c.applicable:0;
  const pages=Number(r?.multiPage?.counts?.audited||1);
  const jsLimited=Boolean(r?.rendering?.warning)||Boolean(r?.rendering?.botProtection?.length);
  // The engine's own self-check can only lower reliability, never raise it.
  const self=r?.selfCheck?.reliability;
  if(self==="low")return "limited";
  if(scoreCov>=.9&&pages>=3&&!jsLimited&&self!=="medium")return "high";
  if(scoreCov>=.7&&pages>=2)return "medium";
  return "limited";
};
const reasonFor=(c:Check,language:Locale)=>{
  const code=(c as any).reasonCode;
  const msg=String(c.message||"").toLowerCase();
  const js=code==="needs_js"||/javascript|client-side|render/.test(msg);
  const weak=code==="weak_evidence"||/onvoldoende|insufficient|niet.*bevestig|unable/.test(msg);
  if(language!=="nl") return c.message||"Evidence was insufficient for a definitive result.";
  if(js)return "Niet te bevestigen omdat dit signaal mogelijk pas na JavaScript-rendering zichtbaar wordt; deze scan gebruikte raw HTML.";
  if(code==="cap_absent"||c.status==="not_applicable")return "Deze controle geldt niet voor dit type website.";
  if(code==="insufficient_pages")return "We analyseerden geen representatieve pagina waarop dit betrouwbaar zichtbaar was.";
  if(code==="type_uncertain")return "Het type bedrijf is niet zeker genoeg om te bepalen of deze controle geldt.";
  if(weak)return "Er zijn aanwijzingen gevonden, maar de beschikbare evidence is te zwak voor een betrouwbare conclusie.";
  return c.message||"Onvoldoende controleerbare evidence in de geselecteerde pagina’s om deze controle betrouwbaar te bevestigen.";
};
