  useEffect(()=>{fetch("/api/account/language").then(r=>r.ok?r.json():null).then(d=>{if(d?.language&&d.language in reportText)setLanguage(d.language)}).catch(()=>{});if(!id)return;fetch("/api/history/"+encodeURIComponent(id),{cache:"no-store"}).then(async r=>{const d=await r.json();if(r.status===401){location.href="/account?next="+encodeURIComponent(window.location.pathname+window.location.search);return;}if(!r.ok)throw new Error(d.error||t.failed);setScan({...d.scan,id});}).catch(e=>setError(e instanceof Error?e.message:t.failed));},[id]);
